import Foundation
import XCTest
#if SWIFT_PACKAGE
@testable import ClaudexCore
#else
@testable import Claudex
#endif

/// Expectations are output from the unmodified current web queue functions, not generated by the Swift
/// implementation. See.
final class CanonicalQueueParityTests: XCTestCase {
    func testTenVectorsFromCurrentWebQueue() throws {
        #if SWIFT_PACKAGE
        let bundle = Bundle.module
        #else
        let bundle = Bundle(for: Self.self)
        #endif
        let url = try XCTUnwrap(bundle.url(forResource: "composer-queue", withExtension: "json", subdirectory: "Fixtures"))
        let vectors = try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)).array!
        XCTAssertEqual(vectors.count, 10)
        for vector in vectors {
            let conversation = try vector["conversation"].decode(Conversation.self)
            var queue = ComposerQueue()
            for original in vector["entries"].array! {
                var entry = QueuedComposerMessage(text: original["text"].string!, attachments: [], conversation: conversation,
                    webSearch: original["webSearch"].bool == true,
                    state: original["state"].string == "steered" ? .steered : .queued,
                    messageID: original["messageId"].string)
                entry.error = original["error"].string
                queue.add(entry, conversationID: conversation.id)
            }
            queue.reconcile(conversation)
            let normalized = JSONValue.array(queue.entries(conversation.id).map { entry in
                .object(["text": .string(entry.text), "state": .string(entry.state.rawValue),
                         "messageId": entry.messageID.map(JSONValue.string) ?? .null,
                         "error": entry.error.map(JSONValue.string) ?? .null])
            })
            XCTAssertEqual(normalized, vector["expected"], vector["name"].string!)
            let nextText = queue.beginNext(conversation)?.entry.text
            XCTAssertEqual(nextText.map(JSONValue.string) ?? .null, vector["next"], vector["name"].string!)
        }
    }
}
